import 'package:flutter_bloc/flutter_bloc.dart';import '../../domain/entities/order_entity.dart';import '../../domain/use_cases/create_order_use_case.dart';
sealed class OrderState{const OrderState();}class OrderInitial extends OrderState{const OrderInitial();}class OrderSubmitting extends OrderState{const OrderSubmitting();}class OrderCreated extends OrderState{const OrderCreated(this.orderId);final String orderId;}class OrderFailure extends OrderState{const OrderFailure(this.message);final String message;}
class OrderCubit extends Cubit<OrderState>{OrderCubit({required CreateOrderUseCase createOrder}):_createOrder=createOrder,super(const OrderInitial());final CreateOrderUseCase _createOrder;Future<void> create(OrderEntity order)async{emit(const OrderSubmitting());try{emit(OrderCreated(await _createOrder(order)));}catch(e){emit(OrderFailure(e.toString()));}}}
